import{_ as t,c as a,o,b0 as r}from"./chunks/framework.BWMBvyU7.js";const l="/programming-docs/assets/image-20220501085957416.B50pOWQw.png",g=JSON.parse('{"title":"LV005-队列简介","description":null,"frontmatter":{"title":"LV005-队列简介","date":"2026-03-13T14:01:46.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/data-structure/queue/126d38c48bb21ee4e7141e23","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-13T14:01:46.494Z","fulluuid":"4e7141e238a9446da3f0d1a71cf06faf","useduuid":"4e7141e23"}},"headers":[],"relativePath":"sdoc/data-structure/queue/126d38c48bb21ee4e7141e23.md","filePath":"sdoc/02-数据结构/15-队列/LV005-队列简介.md","lastUpdated":1773672539000}'),s={name:"sdoc/data-structure/queue/126d38c48bb21ee4e7141e23.md"};function n(i,e,d,c,u,_){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lv005-队列简介" tabindex="-1">LV005-队列简介 <a class="header-anchor" href="#lv005-队列简介" aria-label="Permalink to &quot;LV005-队列简介&quot;">​</a></h1><h2 id="一、队列的概念" tabindex="-1">一、队列的概念 <a class="header-anchor" href="#一、队列的概念" aria-label="Permalink to &quot;一、队列的概念&quot;">​</a></h2><p>队列是限制在两端进行插入操作和删除操作的<strong>线性表</strong>。</p><ul><li><strong>队尾</strong>：允许进行存入操作的一端称为队尾。</li><li><strong>队头</strong>：允许进行删除操作的一端称为队头。</li><li><strong>空队</strong>：当线性表中没有元素时，称为空队。</li><li><strong>入队</strong>：数据元素进队列的过程称为入队。</li><li><strong>出队</strong>：数据元素出队列的过程称为 出队。</li></ul><p>队列的特点是<strong>先进先出</strong>（ FIFO ），数据从队列的一端进，从另一端出，可以由顺序表实现队列的存储结构，称为顺序队列，也可以由链表实现队列的存储结构，称为链式队列。两者的区别仅是顺序表和链表的区别，即在实际的物理空间中，数据集中存储的队列是顺序队列，分散存储的队列是链队列。</p><p>队列可以是单端的，也可以是双端的，但是定要遵循的是先进先出的规则，从一端进，从另一端出。</p><img src="'+l+'" alt="image-20220501085957416" style="zoom:33%;">',7)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
